// data/scienceQuest/units/u7.js: Science for Class 7 (Claude, 2026-11-12). Owner: two Class 7 kids sit their science exam
// on 15 Nov and "right now they have nothing". Three units, 13 topics, each a Learn page + warm-up. Every topic is open
// from the start (openTopics), so the kids can go straight to what they need. Practice papers for
// Class 7 (data/papers/class7SciencePaper*.js) point at these topics, so "Practise this" after a paper lands here.
// Pattern guide: the 2025 Class 7 paper the owner shared (topics and question styles only). Every question is original.
// Quality rules: a why-not on every wrong option, at least one near miss, exactly one defensible answer.
import { q, study, quiz, unit, main, forGrades } from "../../englishQuest/helpers.js";

const C7 = [7];
const u1 = forGrades(unit("sq7-u1", 8, "Life Processes", { openTopics: true }), C7);
const u2 = forGrades(unit("sq7-u2", 9, "Matter & Energy", { openTopics: true }), C7);
const u3 = forGrades(unit("sq7-u3", 10, "Thinking Skills", { openTopics: true }), C7);
const topic = (id, u, order, title) => forGrades(main(id, u.id, order, title, [study(`${id}-study`), quiz(`${id}-warmup`)]), C7);

const plantFood = topic("sq7-plant-food", u1, 1, "Food in Plants");
const digestion = topic("sq7-digestion", u1, 2, "Digestion & Nutrients");
const breathing = topic("sq7-breathing", u1, 3, "Respiration");
const transport = topic("sq7-transport", u1, 4, "Transport & Excretion");
const habitats = topic("sq7-habitats", u1, 5, "Adaptations & Weather");
const acids = topic("sq7-acids", u2, 1, "Acids, Bases & Salts");
const changes = topic("sq7-changes", u2, 2, "Changes & Separation");
const heat = topic("sq7-heat", u2, 3, "Heat");
const motion = topic("sq7-motion", u2, 4, "Motion & Time");
const electricity = topic("sq7-electricity", u2, 5, "Electricity & Magnets");
const light = topic("sq7-light", u2, 6, "Light & Mirrors");
const earth = topic("sq7-earth", u2, 7, "Space, Resources & Air");
const reasoning = topic("sq7-reasoning", u3, 1, "Reasoning Puzzles");

// A Learn page: 3 idea cards + 1 check card, and a short plain page for older readers.
const page = (name, cards, check) => ({
  name,
  author: "Apprec8",
  cards: [...cards.map(([emoji, title, text, examples]) => ({ emoji, title, text, examples })), { kind: "check", ...check }],
  content: cards.map(([emoji, title, text, examples]) => `### ${emoji} ${title}\n\n${text}\n\n${examples.map((e) => `- ${e}`).join("\n")}`).join("\n\n"),
});

